-- .GG.BR ULTIMATE MOBILE EDITION (FULL CODE FOR MANUAL COPY)local P = game:GetService("Players")local Cam = workspace.CurrentCameralocal RS = game:GetService("RunService")local UIS = game:GetService("UserInputService")local TS = game:GetService("TweenService")-- ระบบดักรอจนกว่าตัวเกมและกล้องจะโหลดเสร็จ ป้องกัน GUI พังบนมือถือrepeat task.wait() until P.LocalPlayer and Cam and Cam.ViewportSize.X > 0local LP = P.LocalPlayer_G.GGBR_Settings = {Aim = false,Head = false,ESP = false,FOV = 130,Smoothness = 1.8,LockFOV = true,CenterPos = Vector2.new(Cam.ViewportSize.X / 2, Cam.ViewportSize.Y / 2)}local S = _G.GGBR_Settingslocal Rainbow = Color3.fromRGB(255, 0, 0)local ESP = {}-- วาดวงกลม FOV ดั้งเดิมlocal FOV = Drawing.new("Circle")FOV.Thickness = 2FOV.NumSides = 64FOV.Radius = S.FOVFOV.Filled = falseFOV.Color = Color3.fromRGB(0, 0, 0)FOV.Visible = truetask.spawn(function()local h = 0while task.wait() doh = (h + 1.5) % 360Rainbow = Color3.fromHSV(h / 360, 1, 1)endend)local function isVisible(t)if not t.Character or not t.Character:FindFirstChild("HumanoidRootPart") then return false endlocal p = RaycastParams.new()p.FilterType = Enum.RaycastFilterType.Excludep.FilterDescendantsInstances = {LP.Character, t.Character}local r = workspace:Raycast(Cam.CFrame.Position, t.Character.HumanoidRootPart.Position - Cam.CFrame.Position, p)return not rendlocal function getTarget()local cl = nillocal sh = S.FOVfor _, p in ipairs(P:GetPlayers()) doif p ~= LP and p.Character and p.Character:FindFirstChild("Humanoid") and p.Character.Humanoid.Health > 0 and isVisible(p) thenlocal part = p.Character:FindFirstChild(S.Head and "Head" or "HumanoidRootPart")if part thenlocal pos, on = Cam:WorldToViewportPoint(part.Position)local d = (Vector2.new(pos.X, pos.Y) - S.CenterPos).Magnitudeif on and d < sh thensh = dcl = pendendendendreturn clendlocal function setESP(p, st)if st and not ESP[p] thenESP[p] = {Box = Drawing.new("Square"),BoxBG = Drawing.new("Square"),Tracer = Drawing.new("Line"),TracerShadow = Drawing.new("Line")}ESP[p].Box.Thickness = 2.5ESP[p].Box.Filled = falseESP[p].Box.Color = Color3.fromRGB(0, 210, 255)ESP[p].BoxBG.Thickness = 1ESP[p].BoxBG.Filled = trueESP[p].BoxBG.Color = Color3.fromRGB(0, 210, 255)ESP[p].BoxBG.Transparency = 0.12ESP[p].Tracer.Thickness = 2ESP[p].TracerShadow.Thickness = 4.5ESP[p].TracerShadow.Color = Color3.fromRGB(0, 0, 0)elseif not st and ESP[p] thenpcall(function()ESP[p].Box:Remove()ESP[p].BoxBG:Remove()ESP[p].Tracer:Remove()ESP[p].TracerShadow:Remove()end)ESP[p] = nilendendP.PlayerAdded:Connect(function(p) setESP(p, true) end)P.PlayerRemoving:Connect(function(p) setESP(p, false) end)for _, p in ipairs(P:GetPlayers()) do if p ~= LP then setESP(p, true) end endRS.RenderStepped:Connect(function()if S.LockFOV thenS.CenterPos = Vector2.new(Cam.ViewportSize.X / 2, Cam.ViewportSize.Y / 2)endFOV.Position = S.CenterPosFOV.Radius = S.FOVif S.Aim thenlocal t = getTarget()local part = t and t.Character and t.Character:FindFirstChild(S.Head and "Head" or "HumanoidRootPart")if part thenCam.CFrame = Cam.CFrame:Lerp(CFrame.new(Cam.CFrame.Position, part.Position), 1 / S.Smoothness)FOV.Radius = math.max(S.FOV - 15, FOV.Radius - 1.8)endelseFOV.Radius = math.min(S.FOV, FOV.Radius + 1.8)endfor p, d in pairs(ESP) doif S.ESP and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Character:FindFirstChild("Head") and p.Character.Humanoid.Health > 0 thenlocal headPos, on = Cam:WorldToViewportPoint(p.Character.Head.Position + Vector3.new(0, 0.5, 0))local legPos = Cam:WorldToViewportPoint(p.Character.HumanoidRootPart.Position - Vector3.new(0, 3, 0))if on thenlocal h = math.abs(headPos.Y - legPos.Y)local w = h / 1.55local size = Vector2.new(w, h)local pos = Vector2.new(headPos.X - w / 2, headPos.Y)d.Box.Size = sized.Box.Position = posd.Box.Visible = trued.BoxBG.Size = sized.BoxBG.Position = posd.BoxBG.Visible = truelocal topCenter = Vector2.new(Cam.ViewportSize.X / 2, 0)local targetPos = Vector2.new(headPos.X, headPos.Y)d.TracerShadow.From = topCenterd.TracerShadow.To = targetPosd.TracerShadow.Visible = trued.Tracer.From = topCenterd.Tracer.To = targetPosd.Tracer.Color = Rainbowd.Tracer.Visible = trueelsed.Box.Visible = falsed.BoxBG.Visible = falsed.Tracer.Visible = falsed.TracerShadow.Visible = falseendelsed.Box.Visible = falsed.BoxBG.Visible = falsed.Tracer.Visible = falsed.TracerShadow.Visible = falseendendend)-- ระบบเลื่อนลากวงกลมผ่านการทัชสกรีนหน้าจอมือถือ (เมื่อปลดล็อก)local fovDragging = falseUIS.InputBegan:Connect(function(input, processed)if not processed and not S.LockFOV and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) thenlocal dist = (Vector2.new(input.Position.X, input.Position.Y) - S.CenterPos).Magnitudeif dist <= S.FOV thenfovDragging = trueendendend)UIS.InputChanged:Connect(function(input)if fovDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) thenS.CenterPos = Vector2.new(input.Position.X, input.Position.Y)endend)UIS.InputEnded:Connect(function(input)if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch thenfovDragging = falseendend)-- สร้าง GUI แยกหน้าต่างแบบเชื่อมโยงระบบมือถือlocal UI = Instance.new("ScreenGui")UI.Name = "GGBR_MobileUI"UI.Parent = game:GetService("CoreGui")local function createModuleWindow(titleText, startPos, sizeY)local frame = Instance.new("Frame")frame.Size = UDim2.new(0, 230, 0, sizeY)frame.Position = startPosframe.BackgroundColor3 = Color3.fromRGB(10, 11, 16)frame.Active = trueframe.Draggable = trueframe.Parent = UIlocal corner = Instance.new("UICorner")corner.CornerRadius = UDim.new(0, 10)corner.Parent = framelocal stroke = Instance.new("UIStroke")stroke.Thickness = 2stroke.Color = Color3.fromRGB(0, 210, 255)stroke.Parent = frametask.spawn(function()while task.wait() dostroke.Color = Rainbowendend)local title = Instance.new("TextLabel")title.Size = UDim2.new(1, -10, 0, 32)title.Position = UDim2.new(0, 10, 0, 2)title.BackgroundTransparency = 1title.Text = "⚡ " .. titleText .. "  [.GG.BR]"title.TextColor3 = Color3.fromRGB(255, 255, 255)title.Font = Enum.Font.GothamBoldtitle.TextSize = 11title.TextXAlignment = Enum.TextXAlignment.Lefttitle.Parent = framereturn frameendlocal function makeToggle(parent, text, key, y)local btn = Instance.new("TextButton")btn.Size = UDim2.new(0.92, 0, 0, 32)btn.Position = UDim2.new(0.04, 0, 0, y)btn.BackgroundColor3 = Color3.fromRGB(15, 16, 22)btn.BackgroundTransparency = 0.25btn.Text = "     [ ]  " .. textbtn.TextColor3 = Color3.fromRGB(140, 150, 170)btn.Font = Enum.Font.GothamSemiboldbtn.TextSize = 11btn.TextXAlignment = Enum.TextXAlignment.Leftbtn.ZIndex = 2btn.Parent = parentlocal btnCorner = Instance.new("UICorner")btnCorner.CornerRadius = UDim.new(0, 8)btnCorner.Parent = btnlocal bStroke = Instance.new("UIStroke")bStroke.Thickness = 1.5bStroke.Color = Color3.fromRGB(32, 34, 44)bStroke.Parent = btnlocal function updateVisual()local active = S[key]TS:Create(btn, TweenInfo.new(0.22), {BackgroundColor3 = active and Color3.fromRGB(15, 35, 45) or Color3.fromRGB(15, 16, 22),TextColor3 = active and Color3.fromRGB(0, 255, 200) or Color3.fromRGB(140, 150, 170)}):Play()TS:Create(bStroke, TweenInfo.new(0.22), {Color = active and Color3.fromRGB(0, 255, 200) or Color3.fromRGB(32, 34, 44)}):Play()btn.Text = "     " .. (active and "[✓]" or "[ ]") .. "  " .. textendbtn.MouseButton1Click:Connect(function()S[key] = not S[key]updateVisual()end)if S[key] thenupdateVisual()endendlocal function makeSlider(parent, text, key, min, max, y)local bg = Instance.new("Frame")bg.Size = UDim2.new(0.92, 0, 0, 42)bg.Position = UDim2.new(0.04, 0, 0, y)bg.BackgroundColor3 = Color3.fromRGB(15, 16, 22)bg.BackgroundTransparency = 0.25bg.Parent = parentlocal bgCorner = Instance.new("UICorner")bgCorner.CornerRadius = UDim.new(0, 8)bgCorner.Parent = bglocal stroke = Instance.new("UIStroke")stroke.Thickness = 1.5stroke.Color = Color3.fromRGB(32, 34, 44)stroke.Parent = bglocal label = Instance.new("TextLabel")label.Size = UDim2.new(1, -10, 0, 18)label.Position = UDim2.new(0, 8, 0, 2)label.BackgroundTransparency = 1label.Text = text .. ": " .. tostring(S[key])label.TextColor3 = Color3.fromRGB(180, 190, 210)label.Font = Enum.Font.GothamSemiboldlabel.TextSize = 10label.TextXAlignment = Enum.TextXAlignment.Leftlabel.Parent = bglocal slideBtn = Instance.new("TextButton")slideBtn.Size = UDim2.new(0.92, 0, 0, 10)slideBtn.Position = UDim2.new(0.04, 0, 0, 24)slideBtn.BackgroundColor3 = Color3.fromRGB(30, 35, 48)slideBtn.Text = ""slideBtn.Parent = bglocal sCorner = Instance.new("UICorner")sCorner.CornerRadius = UDim.new(0, 4)sCorner.Parent = slideBtnlocal fill = Instance.new("Frame")fill.Size = UDim2.new((S[key] - min) / (max - min), 0, 1, 0)fill.BackgroundColor3 = Color3.fromRGB(0, 255, 200)fill.BorderSizePixel = 0fill.Parent = slideBtnlocal fillCorner = Instance.new("UICorner")fillCorner.CornerRadius = UDim.new(0, 4)fillCorner.Parent = filllocal dragging = falseslideBtn.InputBegan:Connect(function(i)if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch thendragging = trueendend)UIS.InputEnded:Connect(function(i)if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch thendragging = falseendend)RS.RenderStepped:Connect(function()if dragging thenlocal mPos = UIS:GetMouseLocation()local relX = math.clamp((mPos.X - slideBtn.AbsolutePosition.X) / slideBtn.AbsoluteSize.X, 0, 1)S[key] = math.floor((min + (max - min) * relX) * 10) / 10fill.Size = UDim2.new(relX, 0, 1, 0)label.Text = text .. ": " .. tostring(S[key])endend)end-- 1. หน้าต่าง AIMBOT LOCKlocal WinAim = createModuleWindow("AIMBOT LOCK", UDim2.new(0.05, 0, 0.2, 0), 145)makeToggle(WinAim, "เปิดระบบ ล็อคเป้า (Aimbot)", "Aim", 40)makeToggle(WinAim, "สลับล็อกหัว (เปิด=หัว/ตัว)", "Head", 78)makeSlider(WinAim, "ความสมูท (Smoothness)", "Smoothness", 1, 5, 116)-- 2. หน้าต่าง ESP WALL VISIONlocal WinESP = createModuleWindow("ESP WALL VISION", UDim2.new(0.7, 0, 0.2, 0), 90)makeToggle(WinESP, "เปิดระบบ มองทะลุ (ESP)", "ESP", 40)-- 3. หน้าต่าง FOV CONTROLlocal WinFOV = createModuleWindow("FOV SETTING", UDim2.new(0.38, 0, 0.65, 0), 165)makeToggle(WinFOV, "ล็อกเป้ากลมกลืนกลางจอ (ขยับไม่ได้)", "LockFOV", 40)makeSlider(WinFOV, "ขนาดวงกลม (FOV Radius)", "FOV", 40, 400, 78)local ResetBtn = Instance.new("TextButton")ResetBtn.Size = UDim2.new(0.92, 0, 0, 32)ResetBtn.Position = UDim2.new(0.04, 0, 0, 124)ResetBtn.BackgroundColor3 = Color3.fromRGB(35, 15, 20)ResetBtn.Text = "🔄 รีเซ็ตวงกลมกลับมากลางจอ"ResetBtn.TextColor3 = Color3.fromRGB(255, 100, 100)ResetBtn.Font = Enum.Font.GothamBoldResetBtn.TextSize = 11ResetBtn.Parent = WinFOVlocal rCorner = Instance.new("UICorner")rCorner.CornerRadius = UDim.new(0, 8)rCorner.Parent = ResetBtnlocal rStroke = Instance.new("UIStroke")rStroke.Thickness = 1.5rStroke.Color = Color3.fromRGB(80, 30, 44)rStroke.Parent = ResetBtnResetBtn.MouseButton1Click:Connect(function()S.CenterPos = Vector2.new(Cam.ViewportSize.X / 2, Cam.ViewportSize.Y / 2)TS:Create(ResetBtn, TweenInfo.new(0.1), {BackgroundColor3 = Color3.fromRGB(60, 20, 30)}):Play()task.wait(0.1)TS:Create(ResetBtn, TweenInfo.new(0.1), {BackgroundColor3 = Color3.fromRGB(35, 15, 20)}):Play()end)UIS.InputBegan:Connect(function(i, g)if not g and (i.KeyCode == Enum.KeyCode.Insert or i.KeyCode == Enum.KeyCode.RightShift) thenWinAim.Visible = not WinAim.VisibleWinESP.Visible = not WinESP.VisibleWinFOV.Visible = not WinFOV.Visibleendend)
